-- Personal check-in codes (Decision 315 item 2; this build: Decision 384,
-- front-desk handover F3). Each member has one per School, generated by ULTM8,
-- School."checkInCodeDigits" long and unique in the School: a backup to the
-- app QR, typed on the front-desk keypad. Staff can issue a new one; the
-- member can't change it.

ALTER TYPE "CheckInMethod" ADD VALUE 'PERSONAL_CODE';

CREATE TABLE "StudentCheckInCode" (
    "id" TEXT NOT NULL,
    "schoolId" TEXT NOT NULL,
    "studentId" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,
    CONSTRAINT "StudentCheckInCode_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "StudentCheckInCode_schoolId_fkey" FOREIGN KEY ("schoolId") REFERENCES "School"("id") ON DELETE CASCADE ON UPDATE CASCADE,
    CONSTRAINT "StudentCheckInCode_studentId_fkey" FOREIGN KEY ("studentId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE
);
CREATE UNIQUE INDEX "StudentCheckInCode_schoolId_studentId_key" ON "StudentCheckInCode"("schoolId", "studentId");
CREATE UNIQUE INDEX "StudentCheckInCode_schoolId_code_key" ON "StudentCheckInCode"("schoolId", "code");
CREATE INDEX "StudentCheckInCode_studentId_idx" ON "StudentCheckInCode"("studentId");

GRANT SELECT, INSERT, UPDATE ON "StudentCheckInCode" TO ultm8_app;
-- A code typed on a locked tablet carries no user: the API matches it through ultm8_jobs.
GRANT SELECT ON "StudentCheckInCode" TO ultm8_jobs;

ALTER TABLE "StudentCheckInCode" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "StudentCheckInCode" FORCE ROW LEVEL SECURITY;

-- Staff at the School see the codes and issue new ones. Which students a
-- Branch Staff member or coach covers is checked in the API
-- (assertStaffCoversStudent), as for the rest of a student's page.
CREATE POLICY "student_check_in_code_staff" ON "StudentCheckInCode"
  FOR ALL
  TO ultm8_app
  USING (
    EXISTS (
      SELECT 1 FROM "RoleGrant" rg
      WHERE rg."userId" = current_setting('app.current_user_id', true)
        AND rg."schoolId" = "StudentCheckInCode"."schoolId"
        AND rg."role" IN ('SCHOOL_OWNER_MANAGER', 'BRANCH_STAFF', 'INSTRUCTOR')
        AND rg."revokedAt" IS NULL
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM "RoleGrant" rg
      WHERE rg."userId" = current_setting('app.current_user_id', true)
        AND rg."schoolId" = "StudentCheckInCode"."schoolId"
        AND rg."role" IN ('SCHOOL_OWNER_MANAGER', 'BRANCH_STAFF', 'INSTRUCTOR')
        AND rg."revokedAt" IS NULL
    )
  );

-- The member reads their own code, and their own context creates it the first
-- time it's shown (no UPDATE: they can't change it).
CREATE POLICY "student_check_in_code_self_read" ON "StudentCheckInCode"
  FOR SELECT
  TO ultm8_app
  USING ("studentId" = current_setting('app.current_user_id', true));

CREATE POLICY "student_check_in_code_self_create" ON "StudentCheckInCode"
  FOR INSERT
  TO ultm8_app
  WITH CHECK (
    "studentId" = current_setting('app.current_user_id', true)
    AND EXISTS (
      SELECT 1 FROM "RoleGrant" rg
      WHERE rg."userId" = current_setting('app.current_user_id', true)
        AND rg."schoolId" = "StudentCheckInCode"."schoolId"
        AND rg."role" = 'STUDENT'
        AND rg."revokedAt" IS NULL
    )
  );

-- A Guardian checks a child in with the child's code (Decision 315 item 2).
CREATE POLICY "student_check_in_code_guardian_read" ON "StudentCheckInCode"
  FOR SELECT
  TO ultm8_app
  USING (
    EXISTS (
      SELECT 1 FROM "GuardianLink" gl
      WHERE gl."guardianId" = current_setting('app.current_user_id', true)
        AND gl."studentId" = "StudentCheckInCode"."studentId"
        AND gl."revokedAt" IS NULL
    )
  );

CREATE POLICY "student_check_in_code_jobs_read" ON "StudentCheckInCode"
  FOR SELECT
  TO ultm8_jobs
  USING (true);
